-- rebuild.sql — Modium exact-reconstitution database for idea-vm-010.
-- Idea System(TM) / Idea(TM). From Author; distributive.
-- Portable MySQL/MariaDB: loads with `mysql <db> < rebuild.sql`.
-- Deterministic (sorted rows) so regeneration is idempotent.
-- Each row carries a file's structural metadata + base64 content,
-- so an exact file can be reconstituted when a hash scan fails.

CREATE TABLE IF NOT EXISTS modium_files (
  id        INT AUTO_INCREMENT PRIMARY KEY,
  vm        VARCHAR(32)  NOT NULL DEFAULT 'idea-vm-010',
  path      VARCHAR(1024) NOT NULL,
  name      VARCHAR(256)  NOT NULL,
  parent    VARCHAR(1024) NOT NULL,
  ancestry  VARCHAR(1024) NOT NULL,
  depth     INT           NOT NULL,
  sha256    CHAR(64)      NOT NULL,
  size      BIGINT        NOT NULL,
  seal      CHAR(64)      NOT NULL,
  content_b64 LONGTEXT    NOT NULL,
  UNIQUE KEY uq_vm_path (vm, path)
);

